def instrument(l):
    lines='';scatter=[]
    for i in range(17):
        y=90+i*18; end=120+i*14
        order=[35,y,190,y,255,235,315,235,375,235,405,end,540,end]
        noise=[35,y,260,55+(i*67)%390,90,430-(i*41)%330,305,235+(i%5-2)*35,475,45+(i*57)%350,305,90+(i*39)%310,540,end]
        def path(v):return f'M{v[0]},{v[1]} C{v[2]},{v[3]} {v[4]},{v[5]} {v[6]},{v[7]} S{v[8]},{v[9]} {v[10]},{v[11]} L{v[12]},{v[13]}'
        lines+=f'<path class="signal-line" d="{path(order)}" data-noise="{",".join(map(str,noise))}" data-order="{",".join(map(str,order))}"/>'
    ticks=''.join(f'<line x1="{310+70*math.cos(i*math.pi/24):.2f}" y1="{235+70*math.sin(i*math.pi/24):.2f}" x2="{310+75*math.cos(i*math.pi/24):.2f}" y2="{235+75*math.sin(i*math.pi/24):.2f}"/>' for i in range(48))
    return f'''<div class="instrument" data-instrument><div class="instrument-top"><span class="eyebrow">FIG. 01 / {label(l,'Проявить логику','Find the structure')}</span><span class="instrument-light" aria-hidden="true"></span></div><svg viewBox="0 0 600 465" role="img" aria-label="{label(l,'Несколько входных потоков собираются в объяснимое правило','Multiple input streams become an explainable rule')}"><g class="instrument-grid"><path d="M35 70V410M540 70V410M35 235H555"/></g><g class="signal-lines">{lines}</g><g class="instrument-core"><circle cx="310" cy="235" r="76"/><g class="ticks">{ticks}</g><circle cx="310" cy="235" r="57"/><text x="310" y="237" text-anchor="middle" class="core-label">{label(l,'Логика','Logic')}</text><text x="310" y="256" text-anchor="middle" class="core-sub">INPUT → OUTPUT</text></g><g class="input-dots"><circle cx="35" cy="90" r="4"/><circle cx="35" cy="234" r="4"/><circle cx="35" cy="378" r="4"/></g><g class="instrument-labels"><text x="35" y="48" id="input-label">{label(l,'РАЗНЫЕ УСЛОВИЯ','MANY CONDITIONS')}</text><text x="540" y="48" text-anchor="end" id="output-label">{label(l,'ЯСНОЕ ПРАВИЛО','ONE CLEAR RULE')}</text><text x="35" y="445">01 / {label(l,'РАЗОБРАТЬСЯ','UNDERSTAND')}</text><text x="540" y="445" text-anchor="end">02 / {label(l,'СОБРАТЬ','BUILD')}</text></g></svg><div class="instrument-bottom"><p id="instrument-caption">{label(l,'У каждой сложной задачи есть структура.','Every complex problem has a structure.')}</p><button class="replay" data-replay aria-label="{label(l,'Повторить сборку схемы','Replay the diagram animation')}">{label(l,'Собрать заново','Rebuild')} <span aria-hidden="true">↻</span></button></div><span class="artifact-note">{label(l,'Авторская иллюстрация инженерного подхода','An original illustration of the engineering approach')}</span></div>'''

