def projects(l,pre,order=('tbank','cody','bpmn'),compact=False):
    labels={'tbank':choose(l,'Т-Банк','T-Bank'),'cody':'CODY','bpmn':'BPMN.space'}
    titles={'tbank':choose(l,'Из кода —<br>в правила.','From code<br>to rules.'),'cody':choose(l,'Ближе<br>к своей работе.','Closer<br>to your work.'),'bpmn':choose(l,'Сначала —<br>хороший вопрос.','First,<br>a good question.')}
    summaries={'tbank':choose(l,'Конфигурации продуктовых экспериментов и объяснимые данные.','Product experiment configurations and explainable data.'),'cody':choose(l,'Голос, контекст и рабочие сессии на Mac — с телефона.','Voice, context and Mac work sessions — from your phone.'),'bpmn':choose(l,'От неоднозначного документа к редактируемому процессу.','From an ambiguous document to an editable process.')}
    arts={'tbank':tbank_art,'cody':cody_art,'bpmn':bpmn_art}
    cards=''
    for n,k in enumerate(order):
        cards+=f'''<a class="project project-{k} reveal" href="{link(pre,l,'work/'+k)}"><div class="project-top"><span>{'01' if k=='tbank' else '02' if k=='cody' else '03'} / {labels[k]}</span>{arrow()}</div><div class="project-art">{arts[k](l)}</div><div class="project-bottom"><h3>{titles[k]}</h3><div><p>{summaries[k]}</p><span class="project-status">{e(DATA[l]['cases'][k]['status'])}</span></div></div></a>'''
    return f'<div class="project-grid {"compact" if compact else ""}">{cards}</div>'

